 async prepare(ctx:AuthContext,scope:string,value:any,tx:Transaction){const input=FlowSubmission.parse(value);await this.services.auth.check(ctx,'methods.use',scope,tx);const selected=await this.services.methods.resolve(ctx,scope,input.flowId,tx,input.methodPin),loaded=await this.services.productModules.load(ctx,selected.assetId,scope,tx,input.methodPin),flow=loaded.flows.find((item:any)=>item.id===input.flowId);requireCondition(flow,'SOURCE_NOT_APPROVED','Module flow is unavailable');FlowDefinition.parse(flow);for(const pin of Object.values(input.resources))await providerBinding(this.services,ctx,scope,pin,this.profiles,tx);const sources:any={};for(const [alias,pin]of Object.entries(input.sources))sources[alias]=await this.services.sourceArtifacts.snapshot(ctx,pin.assetId,scope,tx,pin);for(const slot of input.controlledBytes)requireCondition(sources[slot.source]?.files.some((file:any)=>file.path===slot.path&&file.role===slot.role),'SOURCE_FORBIDDEN','Byte slot role or original is outside the approved source');return input;}
